interface EventBusEvents {
  [key: string]: any[];
}

class EventBus {
  private subscribers: Map<string, ((payload: any) => void)[]> = new Map();

  publish<T>(event: string, payload: T): void {
    const handlers = this.subscribers.get(event);
    if (handlers) {
      handlers.forEach(handler => {
        try {
          handler(payload);
        } catch (error) {
          console.error(`Error handling event "${event}":`, error);
        }
      });
    }
  }

  subscribe<T>(event: string, callback: (payload: T) => void): void {
    if (!this.subscribers.has(event)) {
      this.subscribers.set(event, []);
    }
    this.subscribers.get(event)?.push(callback as (payload: any) => void);
  }

  unsubscribe<T>(event: string, callback: (payload: T) => void): void {
    const handlers = this.subscribers.get(event);
    if (handlers) {
      this.subscribers.set(event, handlers.filter(handler => handler !== callback));
    }
  }
}

export const eventBus = new EventBus();

interface User {
  id: string;
  name: string;
  email: string;
}

class UserService {
  private users: Map<string, User> = new Map();
  private nextId: number = 1;

  create(name: string, email: string): User {
    const id = `user-${this.nextId++}`;
    const newUser: User = { id, name, email };
    this.users.set(id, newUser);
    return newUser;
  }

  getById(id: string): User | undefined {
    return this.users.get(id);
  }

  getAll(): User[] {
    return Array.from(this.users.values());
  }

  update(id: string, name: string, email: string): User | undefined {
    const user = this.users.get(id);
    if (user) {
      user.name = name;
      user.email = email;
      return user;
    }
    return undefined;
  }

  delete(id: string): boolean {
    return this.users.delete(id);
  }
}

export const userService = new UserService();

interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
}

class ProjectService {
  private projects: Map<string, Project> = new Map();
  private nextId: number = 1;

  create(name: string, description: string, creatorId: string): Project {
    const id = `proj-${this.nextId++}`;
    const newProject: Project = { id, name, description, memberIds: [creatorId] };
    this.projects.set(id, newProject);
    return newProject;
  }

  getById(id: string): Project | undefined {
    return this.projects.get(id);
  }

  getAll(): Project[] {
    return Array.from(this.projects.values());
  }

  update(id: string, name: string, description: string): Project | undefined {
    const project = this.projects.get(id);
    if (project) {
      project.name = name;
      project.description = description;
      return project;
    }
    return undefined;
  }

  delete(id: string): boolean {
    return this.projects.delete(id);
  }

  addMember(projectId: string, userId: string): boolean {
    const project = this.projects.get(projectId);
    if (project && !project.memberIds.includes(userId)) {
      project.memberIds.push(userId);
      return true;
    }
    return false;
  }

  removeMember(projectId: string, userId: string): boolean {
    const project = this.projects.get(projectId);
    if (project) {
      const initialLength = project.memberIds.length;
      project.memberIds = project.memberIds.filter(memberId => memberId !== userId);
      return project.memberIds.length < initialLength;
    }
    return false;
  }
}

export const projectService = new ProjectService();

import { eventBus } from '../event-bus';

type TaskStatus = 'todo' | 'in-progress' | 'done';

interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId?: string;
  projectId: string;
}

class TaskService {
  private tasks: Map<string, Task> = new Map();
  private nextId: number = 1;

  create(title: string, description: string, projectId: string): Task {
    const id = `task-${this.nextId++}`;
    const newTask: Task = { id, title, description, status: 'todo', projectId };
    this.tasks.set(id, newTask);
    return newTask;
  }

  getById(id: string): Task | undefined {
    return this.tasks.get(id);
  }

  getByProject(projectId: string): Task[] {
    return Array.from(this.tasks.values()).filter(task => task.projectId === projectId);
  }

  getAll(): Task[] {
    return Array.from(this.tasks.values());
  }

  update(id: string, title: string, description: string): Task | undefined {
    const task = this.tasks.get(id);
    if (task) {
      task.title = title;
      task.description = description;
      return task;
    }
    return undefined;
  }

  delete(id: string): boolean {
    return this.tasks.delete(id);
  }

  assign(taskId: string, assigneeId: string): Task | undefined {
    const task = this.tasks.get(taskId);
    if (task) {
      task.assigneeId = assigneeId;
      eventBus.publish('task.assigned', { taskId: task.id, taskTitle: task.title, assigneeId });
      return task;
    }
    return undefined;
  }

  changeStatus(taskId: string, newStatus: TaskStatus): Task | undefined {
    const task = this.tasks.get(taskId);
    if (task) {
      const oldStatus = task.status;
      // Enforce forward-only status transitions
      if (
        (oldStatus === 'todo' && newStatus === 'in-progress') ||
        (oldStatus === 'in-progress' && newStatus === 'done') ||
        (oldStatus === newStatus)
      ) {
        task.status = newStatus;
        if (oldStatus !== newStatus && task.assigneeId) {
          eventBus.publish('task.statusChanged', {
            taskId: task.id,
            taskTitle: task.title,
            assigneeId: task.assigneeId,
            oldStatus,
            newStatus,
          });
        }
        return task;
      } else {
        console.warn(`Invalid status transition for task ${taskId}: ${oldStatus} -> ${newStatus}`);
      }
    }
    return undefined;
  }
}

export const taskService = new TaskService();

import { eventBus } from '../event-bus';

interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: number; // Timestamp
}

class CommentService {
  private comments: Map<string, Comment> = new Map();
  private nextId: number = 1;

  create(taskId: string, authorId: string, authorName: string, body: string, taskTitle: string): Comment {
    const id = `comment-${this.nextId++}`;
    const createdAt = Date.now();
    const newComment: Comment = { id, taskId, authorId, body, createdAt };
    this.comments.set(id, newComment);

    eventBus.publish('comment.added', { commentId: id, taskId, taskTitle, authorId, authorName });
    return newComment;
  }

  getById(id: string): Comment | undefined {
    return this.comments.get(id);
  }

  getByTask(taskId: string): Comment[] {
    return Array.from(this.comments.values()).filter(comment => comment.taskId === taskId);
  }

  delete(id: string): boolean {
    return this.comments.delete(id);
  }
}

export const commentService = new CommentService();
